classDiagram
    BaseNode <|-- TextNode
    BaseNode <|-- FormatNode
    FormatNode <|-- CodeNode
    FormatNode <|-- ThinkNode
    FormatNode <|-- FileCardNode
    FormatNode <|-- SafetyToastNode
    FormatNode <|-- MermaidNode
    FormatNode <|-- LatexNode

    class BaseNode{
        +string nodeId
        +string platform
        +number timestamp
        +parse() void
    }
    class TextNode{
        +string content
        +boolean hasRichText
    }
    class ThinkNode{
        +number reasoningTime
        +boolean isCollapsed
    }
    class FileCardNode{
        +string fileName
        +string fileType
        +string previewUrl
    }
    class SafetyToastNode{
        +string warnType
        +string warnContent
    }
